#!/usr/bin/env bash
set -euo pipefail
echo "NO-GO Stage2 successor execution authority is not committed; historical body is evidence only" >&2; exit 2
ARM="${CEILING1_STAGE2_ARM:?}"; [[ "$ARM" == qwen3-1p7b ]] || { echo "NO-GO qwen3 launcher arm=$ARM" >&2; exit 2; }
C="${CEILING1_STAGE2_CONTAINER:?}"; ROOT="${CEILING1_ANALYSIS_ROOT:?}"; WT="${CEILING1_AUTOPILOT_REPO:?}"; SEEDROOT="${CEILING1_SEED_ROOT:?}"; GPUS="${CEILING1_STAGE2_GPU_UUIDS:?}"; ROUND="${CEILING1_STAGE2_ROUND:?}"; STATE_ID="${CEILING1_STAGE2_STATE_ID:?}"; OUT="${CEILING1_STAGE2_ROUND_ROOT:?}"; SD="${CEILING1_STAGE2_SD_ADAPTER:-}"; CFGSHA="${CEILING1_STAGE2_CONFIG_SHA:?}"
CORE=/workspace/control/openevo-core; MODEL="$ROOT/stage2-base/$ARM"; REV="$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["base_revision"])' "$MODEL/merge-receipt.json")"; SCHEDULE="$WT/configs/experiment/manifests/h1.44-on-3b-training-schedule-v1.json"; MEM="${CEILING1_STAGE2_MEMORY:?}"; SKILL="${CEILING1_STAGE2_SKILL:?}"; AGENT="${CEILING1_STAGE2_AGENT:?}"; HARNESS="${CEILING1_STAGE2_HARNESS_PROFILE:-201.1}"; STEP_SEED="${CEILING1_STAGE2_STEP_SEED_POLICY:-injective-v1}"  # legacy-revision-compat
IFS=',' read -r -a UUIDS <<< "$GPUS"; args=(); for u in "${UUIDS[@]}"; do args+=(--gpu-uuid "$u"); done
state_mounts=(); for P in "$MEM" "$SKILL" "$AGENT"; do case "$P" in "$ROOT"/*) ;; *) state_mounts+=(-v "$P:$P:ro");; esac; done; if [[ -n "$SD" ]]; then case "$SD" in "$ROOT"/*) ;; *) state_mounts+=(-v "$SD:$SD:ro");; esac; fi
start=$((1441 + ROUND*128)); end=$((start+127)); sdargs=(); [[ -n "$SD" ]] && sdargs=(--sd-adapter "$SD")
WORKER="$WT/scripts/openevo_webshop/ceiling1_stage2_rollout_worker_qwen3.py"
[[ -f "$WORKER" ]] || { echo "NO-GO missing Qwen3 rollout worker" >&2; exit 3; }
docker run -d --name "$C" --restart no --tmpfs /tmp:rw,exec,nosuid,size=4g,mode=1777 --gpus "\"device=$GPUS\"" --network none --user 1001:1001 -e HOME=/tmp/openevo-home -e XDG_CACHE_HOME=/tmp/openevo-cache -e HF_HOME=/tmp/huggingface -e TRITON_CACHE_DIR=/tmp/triton -e TMPDIR=/tmp -e TORCHINDUCTOR_CACHE_DIR=/tmp/torchinductor_openevo -e PYTHONDONTWRITEBYTECODE=1 -e TRANSFORMERS_OFFLINE=1 -e HF_HUB_OFFLINE=1 -e PYTHONPATH="$CORE/src:$WT:$WT/vendor/openevo-webshop/src" -v "$CORE:$CORE:ro" -v "$WT:$WT:ro" -v "$ROOT:$ROOT:ro" "${state_mounts[@]}" -v "$OUT:$OUT" -v "$SEEDROOT:$SEEDROOT:ro" --entrypoint /usr/local/bin/python3 experiment-host/openevo-scientific:h144-runtime-v1 "$WT/scripts/openevo_webshop/ceiling1_stage2_round_driver.py" --schedule "$SCHEDULE" --start-position "$start" --end-position "$end" --seed-root "$SEEDROOT" --model "$MODEL" --model-revision "$REV" "${sdargs[@]}" --memory "$MEM" --skill "$SKILL" --agent-system "$AGENT" --output "$OUT" --round-index "$ROUND" --state-id "$STATE_ID" --experiment-git-sha "${CEILING1_STAGE2_EXECUTION_GIT_SHA:-$(git -C "$WT" rev-parse HEAD)}" --config-sha256 "$CFGSHA" --harness-profile "$HARNESS" --step-seed-policy "$STEP_SEED" --worker-script "$WORKER" --resume "${args[@]}"  # legacy-revision-compat
